(6915236, 1042718, 40391, '<td valign="top">Beautiful lighting.</td>', 'Beautiful lighting.', '2012-11-28 13:41:30.000000', NULL, 1),
(6915238, 1042444, 40391, '<td valign="top">Interesting effect - I like.</td>', 'Interesting effect - I like.', '2012-11-28 13:43:14.000000', NULL, 1),
