(6915378, 1042797, 136989, '<td valign="top">Colorful and whimsical.  Love this.</td>', 'Colorful and whimsical.  Love this.', '2012-11-28 17:58:54.000000', NULL, 1),
(6915379, 1042818, 136989, '<td valign="top">I love that the coat sleeve matches the umbrella.  Interesting to choice to have the tree leaves as a background rather than sky but I love how the green makes the colors pop.</td>', 'I love that the coat sleeve matches the umbrella.  Interesting to choice to have the tree leaves as a background rather than sky but I love how the green makes the colors pop.', '2012-11-28 18:00:03.000000', NULL, 1),
