(6915448, 1042510, 155989, '<td valign="top">Oh now this is lovely ... colourful, good sharp reflection, good contrast between the back ground and subjects.</td>', 'Oh now this is lovely ... colourful, good sharp reflection, good contrast between the back ground and subjects.', '2012-11-28 20:11:30.000000', NULL, 1),
